# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ALLAH\'IN ZÂTÎ VE SÜBÛTÎ SIFATLARININ İNSAN HAYATINA YANSIMALARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">ZÂTÎ SIFATLAR VE TEVHİT BİLİNCİ</text>\n  <text x="35" y="88" font-size="10.8" fill="#1e3a8a">• Vücûd: Allah vardır; varlığı zorunludur (Vâcibü\'l-Vücûd).</text>\n  <text x="35" y="108" font-size="10.8" fill="#1e3a8a">• Kıdem &amp; Bekâ: Başlangıcı (ezelî) ve sonu (ebedî) yoktur.</text>\n  <text x="35" y="128" font-size="10.8" fill="#1e3a8a">• Vahdâniyet: Zâtında, sıfatlarında ve fiillerinde birdir.</text>\n  <text x="35" y="148" font-size="10.8" fill="#1e3a8a">• Muhâlefetün li\'l-havâdis: Yaratılmışlara benzemez.</text>\n  <text x="35" y="168" font-size="10.8" fill="#1e3a8a">• Kıyâm bi-nefsihî: Hiçbir varlığa muhtaç değildir.</text>\n  <text x="35" y="190" font-size="10.5" font-weight="bold" fill="#1d4ed8">→ İnsanı şirkten korur, yalnız Allah\'a kulluk bilinci verir.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">SÜBÛTÎ SIFATLAR VE AHLAKİ SORUMLULUK</text>\n  <text x="370" y="88" font-size="10.8" fill="#14532d">• Hayat &amp; İlim: Her şeyi bilir; gizli-açık hiçbir şey saklı kalmaz.</text>\n  <text x="370" y="108" font-size="10.8" fill="#14532d">• Semi\' &amp; Basar: Her sesi işitir ve her şeyi görür (İhsan bilinci).</text>\n  <text x="370" y="128" font-size="10.8" fill="#14532d">• İrade &amp; Kudret: Dilediğini sınırsız gücüyle takdir eder.</text>\n  <text x="370" y="148" font-size="10.8" fill="#14532d">• Kelâm: Vahiy ve ilahi kitaplarla kullarına hitap eder.</text>\n  <text x="370" y="168" font-size="10.8" fill="#14532d">• Tekvîn: Yoktan var eder, rızık ve nimetleri yaratır.</text>\n  <text x="370" y="190" font-size="10.5" font-weight="bold" fill="#15803d">→ İnsanda öz denetim, tevekkül, şükür ve doğruluk sağlar.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Marifetullah: Allah\'ı güzel isimleri (Esmâ-i Hüsnâ) ve sıfatlarıyla gereği gibi tanıma bilincidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ESMÂ-İ HÜSNÂ\'NIN GÜNLÜK İLETİŞİM VE AHLAKA YANSIMALARI</text>\n  <rect x="20" y="42" width="210" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">MERHAMET VE AFFEDİCİLİK</text>\n  <text x="32" y="88" font-size="10.8" fill="#78350f">• Er-Rahmân &amp; Er-Rahîm</text>\n  <text x="32" y="108" font-size="10.8" fill="#78350f">• El-Gaffâr, El-Afüvv, Et-Tevvâb</text>\n  <text x="32" y="130" font-size="10.5" fill="#78350f">Ahlaki Yansıması:</text>\n  <text x="32" y="148" font-size="10.5" fill="#78350f">Mümin ümitsizliğe düşmez; tüm</text>\n  <text x="32" y="165" font-size="10.5" fill="#78350f">canlılara şefkatli, bağışlayıcı ve</text>\n  <text x="32" y="182" font-size="10.5" fill="#78350f">merhametli davranır.</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">ADALET, GÜVEN VE BARIŞ</text>\n  <text x="257" y="88" font-size="10.8" fill="#581c87">• El-Adl &amp; El-Hakem</text>\n  <text x="257" y="108" font-size="10.8" fill="#581c87">• Es-Selâm &amp; El-Mü\'min</text>\n  <text x="257" y="130" font-size="10.5" fill="#581c87">Ahlaki Yansıması:</text>\n  <text x="257" y="148" font-size="10.5" fill="#581c87">Toplumda haksızlıktan kaçınır,</text>\n  <text x="257" y="165" font-size="10.5" fill="#581c87">eline ve diline güvenilen barış</text>\n  <text x="257" y="182" font-size="10.5" fill="#581c87">ve emniyet insanı olur.</text>\n  <rect x="470" y="42" width="210" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">PAYLAŞMA VE BİLGECE HAREKET</text>\n  <text x="482" y="88" font-size="10.8" fill="#064e3b">• Er-Rezzâk &amp; El-Kerîm</text>\n  <text x="482" y="108" font-size="10.8" fill="#064e3b">• El-Alîm &amp; El-Hakîm</text>\n  <text x="482" y="130" font-size="10.5" fill="#064e3b">Ahlaki Yansıması:</text>\n  <text x="482" y="148" font-size="10.5" fill="#064e3b">Rızkı verenin Allah olduğunu bilir,</text>\n  <text x="482" y="165" font-size="10.5" fill="#064e3b">cömertçe infak eder; işlerini ilim</text>\n  <text x="482" y="182" font-size="10.5" fill="#064e3b">ve hikmetle yürütür.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">«En güzel isimler (el-Esmâü\'l-Hüsnâ) Allah\'ındır; O\'na o güzel isimleriyle dua edin.» (A\'râf, 7/180)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">İSLAM VE SOSYAL HAYAT: BİREY - TOPLUM DENGESİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">BİREYSEL HAK VE SORUMLULUKLAR</text>\n  <text x="35" y="88" font-size="11" fill="#1e3a8a">• İnsan akıl ve irade sahibi bir mükelleftir.</text>\n  <text x="35" y="110" font-size="11" fill="#1e3a8a">• Temel haklar (can, akıl, din, nesil, mal) dokunulmazdır.</text>\n  <text x="35" y="132" font-size="11" fill="#1e3a8a">• Her birey kendi amelinden bizzat sorumludur.</text>\n  <text x="35" y="154" font-size="11" fill="#1e3a8a">• Özel hayatın gizliliği (mahremiyet) esastır.</text>\n  <text x="35" y="176" font-size="11" fill="#1e3a8a">• Tevhit inancı insanı kula kul olmaktan özgürleştirir.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">TOPLUMSAL DAYANIŞMA VE İLKELER</text>\n  <text x="370" y="88" font-size="11" fill="#7c2d12">• Müminler bir binanın kenetlenmiş tuğlaları gibidir.</text>\n  <text x="370" y="110" font-size="11" fill="#7c2d12">• Adalet, emanet, sıdk ve merhamet toplumu ayakta tutar.</text>\n  <text x="370" y="132" font-size="11" fill="#7c2d12">• İnfak, zekât ve sadaka sosyal uçurumları giderir.</text>\n  <text x="370" y="154" font-size="11" fill="#7c2d12">• İyiliği emredip kötülükten sakındırma (Emir bi\'l-ma\'rûf).</text>\n  <text x="370" y="176" font-size="11" fill="#7c2d12">• Kul hakkına riayet ve komşuluk hukuku.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">İslam ne bireyi topluma feda eder ne de bencil bireyciliğe izin verir; hak ve ödev dengesini kurar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
